import { CommonModule } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { timeout } from 'rxjs';

interface Question {
  id: number;
  text: string;
  choices: string[];
  correctIndex: number;
  topic: string;
  explanation: string;
}

interface QuizTopic {
  id: string;
  label: string;
  questionCount: number;
}

interface AnswerPayload {
  questionId: number;
  selectedIndex: number;
  topic: string;
}

interface AnswerResult {
  correct: boolean;
  feedback: string;
  explanation?: string | null;
}

interface BatchAnswerResponse {
  totalQuestions: number;
  correctAnswers: number;
  percentage: number;
  message: string;
}

interface VisitCounterResponse {
  count: number;
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  private readonly http = inject(HttpClient);
  private readonly apiTimeoutMs = 5000;

  readonly questionsPerPage = 10;

  topics: QuizTopic[] = [];
  allQuestions: Question[] = [];
  selectedTopic = '';
  answers: Record<number, number> = {};
  results: Record<number, AnswerResult> = {};

  currentPage = 1;
  loading = false;
  errorMessage = '';
  finalResult: BatchAnswerResponse | null = null;
  visitCount: number | null = null;

  constructor() {
    this.trackVisit();
    this.loadTopics();
  }

  get pagedQuestions(): Question[] {
    const startIndex = (this.currentPage - 1) * this.questionsPerPage;
    return this.allQuestions.slice(startIndex, startIndex + this.questionsPerPage);
  }

  get totalPages(): number {
    return Math.max(1, Math.ceil(this.allQuestions.length / this.questionsPerPage));
  }

  get allAnswered(): boolean {
    return this.allQuestions.length > 0
      && this.allQuestions.every((question) => this.answers[question.id] !== undefined);
  }

  get selectedTopicLabel(): string {
    if (!this.selectedTopic) {
      return 'Topic';
    }

    return this.topics.find((topic) => topic.id === this.selectedTopic)?.label ?? this.selectedTopic;
  }

  loadTopics(): void {
    this.loading = true;
    this.errorMessage = '';

    this.http.get<QuizTopic[]>('/api/topics')
      .pipe(timeout(this.apiTimeoutMs))
      .subscribe({
      next: (topics) => {
        this.topics = topics;
        this.loading = false;
        this.allQuestions = [];
      },
      error: () => {
        this.loading = false;
        this.errorMessage = 'Unable to load topics. If you are running locally, start the API with `npm run serve:api`.';
      }
    });
  }

  private trackVisit(): void {
    this.http.post<VisitCounterResponse>('/api/visits', {})
      .pipe(timeout(this.apiTimeoutMs))
      .subscribe({
        next: (response) => {
          this.visitCount = response.count;
        },
        error: () => {
          this.visitCount = null;
        }
      });
  }

  trackQuestion(_index: number, question: Question): number {
    return question.id;
  }

  trackChoice(index: number): number {
    return index;
  }

  trackTopic(_index: number, topic: QuizTopic): string {
    return topic.id;
  }

  chooseTopic(topicId: string): void {
    if (this.selectedTopic === topicId) {
      return;
    }

    this.selectedTopic = topicId;
    this.answers = {};
    this.results = {};
    this.finalResult = null;
    this.currentPage = 1;
    this.loadQuestionsForTopic(topicId);
  }

  private loadQuestionsForTopic(topicId: string): void {
    this.loading = true;
    this.errorMessage = '';

    this.http.get<Question[]>(`/api/questions?topic=${encodeURIComponent(topicId)}`)
      .pipe(timeout(this.apiTimeoutMs))
      .subscribe({
        next: (questions) => {
          this.allQuestions = questions;
          this.loading = false;
        },
        error: () => {
          this.allQuestions = [];
          this.loading = false;
          this.errorMessage = 'Unable to load questions for the selected topic.';
        }
      });
  }

  setAnswer(questionId: number, selectedIndex: number): void {
    this.answers[questionId] = selectedIndex;
  }

  clearAnswer(questionId: number): void {
    delete this.answers[questionId];
    delete this.results[questionId];
  }

  submitSingleAnswer(questionId: number): void {
    const selectedIndex = this.answers[questionId];

    if (selectedIndex === undefined) {
      this.results[questionId] = {
        correct: false,
        feedback: 'Please select an answer before submitting.'
      };
      return;
    }

    const payload: AnswerPayload = { questionId, selectedIndex, topic: this.selectedTopic };
    this.http.post<AnswerResult>('/api/submit', payload)
      .pipe(timeout(this.apiTimeoutMs))
      .subscribe({
      next: (result) => {
        this.results[questionId] = result;
      },
      error: () => {
        this.results[questionId] = {
          correct: false,
          feedback: 'Error submitting answer. Please try again.'
        };
      }
    });
  }

  submitAllAnswers(): void {
    if (!this.allAnswered) {
      this.finalResult = {
        totalQuestions: this.allQuestions.length,
        correctAnswers: 0,
        percentage: 0,
        message: 'Please answer all questions before submitting.'
      };
      return;
    }

    const payload = {
      topic: this.selectedTopic,
      answers: Object.entries(this.answers).map(([questionId, selectedIndex]) => ({
        questionId: Number(questionId),
        selectedIndex
      }))
    };

    this.http.post<BatchAnswerResponse>('/api/submit-all', payload)
      .pipe(timeout(this.apiTimeoutMs))
      .subscribe({
      next: (result) => {
        this.finalResult = result;
      },
      error: () => {
        this.finalResult = {
          totalQuestions: this.allQuestions.length,
          correctAnswers: 0,
          percentage: 0,
          message: 'Error submitting answers. Please try again.'
        };
      }
    });
  }

  goToPage(page: number): void {
    if (page < 1 || page > this.totalPages) {
      return;
    }
    this.currentPage = page;
  }

  formatExplanation(explanation: string | null | undefined): string {
    if (!explanation) {
      return '';
    }

    return this.wrapJavaBlocks(explanation);
  }

  formatQuestionText(text: string | null | undefined): string {
    if (!text) {
      return '';
    }

    return this.wrapJavaBlocks(text);
  }

  private wrapJavaBlocks(content: string): string {
    return content.replace(
      /<pre>\s*<code class="language-java">([\s\S]*?)<\/code>\s*<\/pre>/g,
      '<div class="java-snippet"><div class="java-snippet-label">Java</div><pre><code class="language-java">$1</code></pre></div>'
    );
  }
}
<div class="app-shell">
  <header class="hero">
    <p class="eyebrow">{{ selectedTopicLabel }} Topic Quiz</p>
    <h1>Multiple Choice Quiz</h1>
    <p class="hero-copy">
      Pick one topic, answer only questions from that topic, and review explanations for the ones you get right.
    </p>
    <p class="disclaimer-banner">
      Disclaimer: These questions and explanations were prepared with AI assistance and may contain hallucinations or inaccuracies, so they should not be treated as 100% correct.
    </p>
    <p *ngIf="visitCount !== null" class="visit-counter">
      Total app visits recorded: {{ visitCount }}
    </p>
  </header>

  <section *ngIf="errorMessage" class="status-card error">
    {{ errorMessage }}
  </section>

  <section class="topic-selector-card">
    <div class="topic-selector-copy">
      <h2>Choose A Topic</h2>
      <p>Select one topic to load the matching quiz file.</p>
    </div>

    <div class="topic-chip-list">
      <button
        *ngFor="let topic of topics; trackBy: trackTopic"
        type="button"
        class="topic-chip"
        [class.selected]="selectedTopic === topic.id"
        (click)="chooseTopic(topic.id)"
      >
        <span>{{ topic.label }}</span>
        <small>{{ topic.questionCount }} questions</small>
      </button>
    </div>
  </section>

  <section *ngIf="loading" class="status-card">
    Loading {{ selectedTopic ? 'questions' : 'topics' }}...
  </section>

  <section *ngIf="!loading && !selectedTopic && !errorMessage" class="status-card">
    Choose a topic above to start the quiz.
  </section>

  <ng-container *ngIf="!loading && selectedTopic && !errorMessage">
    <section
      *ngFor="let question of pagedQuestions; trackBy: trackQuestion"
      class="question-card"
    >
      <div class="question-topic">{{ question.topic }}</div>
      <div
        class="question-text"
        [innerHTML]="formatQuestionText(question.text)"
      ></div>

      <div class="choices">
        <label
          *ngFor="let choice of question.choices; let choiceIndex = index; trackBy: trackChoice"
          class="choice-label"
        >
          <input
            type="radio"
            [name]="'question-' + question.id"
            [value]="choiceIndex"
            [ngModel]="answers[question.id]"
            (ngModelChange)="setAnswer(question.id, choiceIndex)"
          />
          <span>{{ choice }}</span>
        </label>
      </div>

      <div class="button-group">
        <button type="button" class="clear-button" (click)="clearAnswer(question.id)">
          Clear
        </button>
        <button type="button" class="submit-button" (click)="submitSingleAnswer(question.id)">
          Submit
        </button>
      </div>

      <div
        *ngIf="results[question.id] as result"
        class="question-result"
        [class.success]="result.correct"
        [class.error]="!result.correct"
      >
        <div class="question-feedback">{{ result.feedback }}</div>
        <div
          *ngIf="result.correct && result.explanation"
          class="question-explanation"
          [innerHTML]="formatExplanation(result.explanation)"
        ></div>
      </div>
    </section>

    <nav *ngIf="totalPages > 1" class="pagination-nav">
      <button
        type="button"
        class="pagination-button"
        [disabled]="currentPage === 1"
        (click)="goToPage(currentPage - 1)"
      >
        ← Previous
      </button>

      <span class="page-info">Page {{ currentPage }} of {{ totalPages }}</span>

      <button
        type="button"
        class="pagination-button"
        [disabled]="currentPage === totalPages"
        (click)="goToPage(currentPage + 1)"
      >
        Next →
      </button>
    </nav>

    <section class="final-submit-panel">
      <button type="button" class="final-submit-button" (click)="submitAllAnswers()">
        Submit All Answers
      </button>
    </section>

    <section
      *ngIf="finalResult"
      class="score-card"
      [class.pass]="finalResult.percentage >= 50"
      [class.fail]="finalResult.percentage < 50"
    >
      <div class="score-message">{{ finalResult.message }}</div>
      <div *ngIf="allAnswered" class="score-details">
        <span>Correct: {{ finalResult.correctAnswers }}/{{ finalResult.totalQuestions }}</span>
        <span>Percentage: {{ finalResult.percentage.toFixed(1) }}%</span>
      </div>
    </section>
  </ng-container>

  <footer class="page-disclaimer">
    AI-generated quiz content may be imperfect. Please verify important answers independently.
  </footer>
</div>
